document.addEventListener('jet-smart-filters/inited', function () {
  var select = document.querySelector('#solution_filter_add .jet-select__control');

  if (select) {
    // Remove a opção "Select..." (value vazia)
    var emptyOption = select.querySelector('option[value=""]');
    if (emptyOption) {
      emptyOption.remove();
    }

    // Seleciona a primeira opção da lista
    if (select.options.length > 0) {
      select.selectedIndex = 0;

      // Dispara o evento 'change' para aplicar o filtro
      var event = new Event('change', { bubbles: true });
      select.dispatchEvent(event);
    }
  }
});
